export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
};

// In-memory store for posts (replace with database in production)
const postsStore: Post[] = [];
let idCounter = 1;

export function createPostInStore(title: string, content: string): Post {
  const post: Post = {
    id: String(idCounter++),
    title,
    content,
    createdAt: new Date(),
  };
  postsStore.push(post);
  return post;
}

export async function getPosts(): Promise<Post[]> {
  const getCachedPosts = unstable_cache(
    async () => [...postsStore],
    ['posts-list'],
    { tags: ['posts'] }
  );
  return getCachedPosts();
}

