'use server';

import { updateTag, refresh } from 'next/cache';
import { createPostInStore } from '@/lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title?.trim() || !content?.trim()) {
    return { error: 'Title and content are required' };
  }

  createPostInStore(title.trim(), content.trim());

  // Invalidate the "posts" cache tag - guarantees next request fetches fresh data
  // (no stale content served, unlike revalidateTag with stale-while-revalidate)
  updateTag('posts');

  // Invalidate client Router Cache so the page re-fetches from server
  refresh();
}

